export const meta = {
  name: 'ping-pong',
  description: 'Two parallel OK pings, then one DONE pong',
  phases: [{ title: 'Ping' }, { title: 'Pong' }],
}

phase('Ping')
const [a, b] = await parallel([
  () => agent('Reply with the single word OK and nothing else.', { label: 'ping:a', phase: 'Ping' }),
  () => agent('Reply with the single word OK and nothing else.', { label: 'ping:b', phase: 'Ping' }),
])

phase('Pong')
const pong = await agent('Reply with the single word DONE and nothing else.', { label: 'pong', phase: 'Pong' })

return { ping: [a, b], pong }

